/**
 * frontend/src/components/CameraRecognition.jsx
 * VERSION AMÉLIORÉE AVEC :
 * - Bounding box visage (canvas overlay)
 * - Feedback audio (succès / erreur)
 * - Comparaison visuelle (photo enregistrée vs capture)
 * - Statut + compteur tentatives
 * - Robustesse API + nettoyage caméra
 */

import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  success: '#10B981',
  error: '#EF4444',
  primary: '#4F46E5',
  background: '#F8FAFC',
  text: '#1E293B'
};

/**
 * ============ AUDIO FEEDBACK ============
 */
const playBeep = (type = 'success') => {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const oscillator = ctx.createOscillator();
    const gain = ctx.createGain();

    oscillator.type = 'sine';
    oscillator.frequency.value = type === 'success' ? 800 : 200;

    gain.gain.value = 0.1;

    oscillator.connect(gain);
    gain.connect(ctx.destination);

    oscillator.start();
    setTimeout(() => {
      oscillator.stop();
      ctx.close();
    }, 200);
  } catch (e) {
    console.warn('Audio non supporté');
  }
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);

  const [autoMode, setAutoMode] = useState(true);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('IDLE');
  const [attempts, setAttempts] = useState(0);
  const [lastTime, setLastTime] = useState(null);

  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredImage, setRegisteredImage] = useState(null);

  const processingRef = useRef(false);

  /**
   * ============ CAMERA START ============
   */
  useEffect(() => {
    const start = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user' },
          audio: false
        });

        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;

        setStatus('SCANNING');
      } catch (err) {
        setStatus('ERROR');
        addNotification('Impossible d’accéder à la caméra', 'error');
      }
    };

    start();

    return () => stopCamera();
  }, []);

  /**
   * ============ DRAW FACE BOX ============
   */
  const drawBox = (box) => {
    const canvas = canvasRef.current;
    const video = videoRef.current;
    if (!canvas || !video || !box) return;

    const ctx = canvas.getContext('2d');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.error;
    ctx.lineWidth = 3;
    ctx.strokeRect(box.x, box.y, box.w, box.h);
  };

  /**
   * ============ CAPTURE FRAME ============
   */
  const captureFrame = () => {
    const video = videoRef.current;
    if (!video) return null;

    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0);

    const base64 = canvas.toDataURL('image/jpeg', 0.9);
    setCapturedImage(base64);

    return base64;
  };

  /**
   * ============ SCAN LOOP ============
   */
  useEffect(() => {
    if (!autoMode) return;

    intervalRef.current = setInterval(async () => {
      if (processingRef.current) return;

      processingRef.current = true;
      setAttempts((a) => a + 1);

      const imageBase64 = captureFrame();
      if (!imageBase64) {
        processingRef.current = false;
        return;
      }

      try {
        const res = await attendanceAPI.recognize(imageBase64);
        const data = res?.data;

        if (data?.success && data?.student) {
          setStatus('SUCCESS');
          setResult(data);
          setLastTime(new Date().toLocaleTimeString());

          setRegisteredImage(data.student_image || null);

          playBeep('success');
          addNotification(`Étudiant reconnu : ${data.student}`, 'success');

          drawBox(data.face_box);

        } else {
          setStatus('ERROR');
          playBeep('error');

          if (!data?.message) {
            addNotification('Aucun visage détecté', 'error');
          } else {
            addNotification(data.message, 'error');
          }
        }
      } catch (err) {
        setStatus('ERROR');
        playBeep('error');
        addNotification('Erreur serveur reconnaissance', 'error');
      } finally {
        processingRef.current = false;
      }
    }, 700);

    return () => clearInterval(intervalRef.current);
  }, [autoMode]);

  /**
   * ============ STOP CAMERA ============
   */
  const stopCamera = () => {
    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }

    if (videoRef.current) videoRef.current.srcObject = null;

    setStatus('IDLE');
  };

  /**
   * ============ MANUAL CAPTURE ============
   */
  const manualCapture = async () => {
    setLoading(true);
    const image = captureFrame();

    try {
      const res = await attendanceAPI.recognize(image);
      const data = res?.data;

      if (data?.success) {
        setResult(data);
        setStatus('SUCCESS');
        playBeep('success');
      } else {
        setStatus('ERROR');
        playBeep('error');
      }
    } catch {
      setStatus('ERROR');
      playBeep('error');
    }

    setLoading(false);
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>Reconnaissance Faciale</h2>

      <div style={styles.videoWrapper}>
        <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
        <canvas ref={canvasRef} style={styles.canvas} />

        <div style={styles.status}>
          Statut : {status} | Tentatives : {attempts}
        </div>
      </div>

      {/* ACTIONS */}
      <div style={styles.actions}>
        <button onClick={manualCapture} disabled={loading}>
          📸 Capturer
        </button>
        <button onClick={() => setAutoMode(!autoMode)}>
          {autoMode ? '⏹ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>
        <button onClick={stopCamera}>🛑 Fermer Caméra</button>
      </div>

      {/* COMPARISON */}
      {result && (
        <div style={styles.compare}>
          <div>
            <h4>Photo capturée</h4>
            {capturedImage && (
              <img src={capturedImage} alt="capture" style={styles.img} />
            )}
          </div>

          <div>
            <h4>Photo enregistrée</h4>
            {registeredImage ? (
              <img src={registeredImage} alt="db" style={styles.img} />
            ) : (
              <p>Aucune image</p>
            )}
          </div>
        </div>
      )}

      {/* RESULT */}
      {result && (
        <div style={styles.result}>
          {result.student ? (
            <>
              <p style={{ color: COLORS.success }}>
                Reconnu : {result.student}
              </p>
              <p>Email : {result.email}</p>
              <p>Confiance : {result.confidence}</p>
              <p>Heure : {lastTime}</p>
            </>
          ) : (
            <p style={{ color: COLORS.error }}>Échec reconnaissance</p>
          )}
        </div>
      )}

      {/* DEBUG */}
      <div style={styles.debug}>
        <p>Mode Auto: {autoMode ? 'ON' : 'OFF'}</p>
        <p>Traitement: {processingRef.current ? 'Oui' : 'Non'}</p>
      </div>
    </div>
  );
};

const styles = {
  container: { padding: 20 },
  title: { color: COLORS.text },
  videoWrapper: { position: 'relative' },
  video: { width: '100%', borderRadius: 10 },
  canvas: { position: 'absolute', top: 0, left: 0 },
  status: { marginTop: 10 },
  actions: { display: 'flex', gap: 10, marginTop: 10 },
  compare: { display: 'flex', gap: 20, marginTop: 20 },
  img: { width: 150, borderRadius: 8 },
  result: { marginTop: 20 },
  debug: { marginTop: 20, fontSize: 12, color: '#666' }
};

export default CameraRecognition;
